constructor(opts: AdoClientOptions = {}) {
  // Config comes from the caller, else the shared loadConfig() seam.
  this.cfg = opts.config ?? loadConfig().ado;
  // offline was already derived by loadConfig as `!pat` — no PAT, no live store.
  this.offline = this.cfg.offline;
  // Basic base64(':' + PAT) — the single definition of the auth that was
  // copy-pasted across the codebase.
  const pat = this.cfg.patWrite || this.cfg.pat || ''; // prefer the write-scoped PAT.
  // ADO wants the token in the PASSWORD half of Basic (empty user), hence ':' + PAT.
  this.authHeader = `Basic ${Buffer.from(`:${pat}`).toString('base64')}`;

  if (this.offline) {
    // Back every call onto local JSON fixtures instead of the network.
    const dir = opts.fixtureDir || path.resolve(__dirname, '..', '..', 'fixtures', 'ado');
    // persist defaults to false so a demo never writes back to committed fixtures.
    this.store = new FixtureStore(dir, opts.persist ?? false);
  } else {
    this.store = null; // live mode: real REST calls only, no fixture store.
  }
}

function normalize(raw: RawWorkItem): WorkItem {
  const f = raw.fields || {}; // fixtures/partial payloads may omit fields entirely.
  const tagsRaw = (f[F.tags] as string) || '';
  // Relation URLs are opaque; extract the numeric target id from each up front.
  const relations: WorkItemRelation[] = (raw.relations || []).map(r => ({
    rel: r.rel,
    url: r.url,
    targetId: targetIdFromUrl(r.url),
  }));
  return {
    id: raw.id,
    type: (f[F.type] as string) || 'Unknown', // never leave type undefined downstream.
    title: (f[F.title] as string) || '',
    state: (f[F.state] as string) || '',
    assignedTo: displayName(f[F.assignedTo]), // {displayName,...} object -> plain string.
    // Split the ';'-joined ADO tag string, but only when non-empty (avoids ['']).
    tags: tagsRaw ? tagsRaw.split(';').map(t => t.trim()).filter(Boolean) : [],
    fields: f, // keep the raw bag too, for callers needing a field we didn't map.
    relations,
  };
}

async getWorkItem(id: number): Promise<WorkItem> {
  if (this.store) {
    const raw = this.store.get(id);
    // Offline miss is a hard error, not a silent null — surfaces bad fixture ids.
    if (!raw) throw new Error(`[ado:offline] work item ${id} not found in fixtures`);
    return normalize(raw);
  }
  // Live: $expand=relations so parent/child links come back with the item.
  const raw = await this.request<RawWorkItem>('GET', `/wit/workitems/${id}?$expand=relations`);
  return normalize(raw);
}

async createWorkItem(type: string, item: NewWorkItem): Promise<WorkItem> {
  // Build the JSON-Patch doc once; both branches below replay the same patches.
  const patches = patchesFor(item, this.cfg.apiBase);
  if (this.store) {
    const id = this.store.nextId(); // offline: mint the next fixture id.
    const raw: RawWorkItem = { id, fields: {}, relations: [] };
    raw.fields[F.type] = type;
    applyPatchesToRaw(raw, patches); // same patches, applied to an in-memory item.
    this.store.put(raw);
    return normalize(raw);
  }
  // '$' before the type is ADO's literal syntax (/wit/workitems/$Bug); the '$$'
  // escapes it in the template string. Trailing `true` = a json-patch write.
  const raw = await this.request<RawWorkItem>(
    'POST', `/wit/workitems/$${encodeURIComponent(type)}`, patches, true);
  return normalize(raw);
}

async getTestPoints(suiteId: number, planId?: number): Promise<TestPoint[]> {
  if (this.store) {
    // Synthesize a point per Test Case fixture (pointId = 900000 + tcId).
    // The 900000 offset keeps synthetic point ids clear of real work-item ids.
    return this.store
      .all()
      .filter(raw => ((raw.fields[F.type] as string) || '').toLowerCase() === 'test case')
      .map(raw => ({ id: 900000 + raw.id, testCaseId: raw.id, suiteId }));
  }
  const pid = planId ?? this.cfg.testPlanId; // fall back to the configured plan.
  const res = await this.request<{ value?: unknown[] }>(
    'GET', `/testplan/plans/${pid}/suites/${suiteId}/testpoint`);
  // testCaseReference may be missing on odd points — default that id to 0.
  return (res.value || []).map(p => ({ id: p.id, testCaseId: p.testCaseReference?.id ?? 0, suiteId }));
}

async fileOne(failure: TestFailure, opts: BugFilerOptions = {}): Promise<FiledBug> {
  const bugType = opts.bugType ?? DEFAULTS.bugType;
  // Stable, greppable title; environment is appended only when present.
  const title = `[Test Failure] ${failure.test}${failure.environment ? ` (${failure.environment})` : ''}`;

  if (opts.dedupe) {
    // Reuse an already-open matching bug instead of filing a duplicate on re-run.
    const existing = await this.findOpenBug(title, bugType);
    if (existing) return { test: failure.test, bugId: existing.id, title, action: 'reused' };
  }
  // Preview mode: report what WOULD be filed, write nothing (null bugId).
  if (opts.dryRun) return { test: failure.test, bugId: null, title, action: 'would-create' };

  const newItem: NewWorkItem = {
    title,
    fields: { 'System.Description': reproHtml(failure) }, // repro rendered as HTML.
    // Hang the bug under its story via a parent relation, when the parent is known.
    relations: failure.parentId ? [{ rel: DEFAULTS.parentRel, targetId: failure.parentId }] : [],
  };
  const bug = await this.client.createWorkItem(bugType, newItem);
  return { test: failure.test, bugId: bug.id, title, action: 'created' };
}
